-- Name: accept_shift_swap_request(uuid, text); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.accept_shift_swap_request(p_request_id uuid, p_acceptance_note text DEFAULT ''::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_req public.shift_swap_requests%rowtype;
  v_shift public.shifts%rowtype;
begin
  v_org_id := public.current_organization_id(auth.uid());
  if v_org_id is null then
    raise exception 'Organization context is required.';
  end if;

  select *
    into v_req
  from public.shift_swap_requests r
  where r.id = p_request_id
    and r.organization_id = v_org_id;

  if v_req.id is null then
    raise exception 'Swap request not found.';
  end if;

  if v_req.status <> 'open' then
    raise exception 'Only open requests can be accepted.';
  end if;

  if v_req.requester_id = auth.uid() then
    raise exception 'Requester cannot accept their own swap request.';
  end if;

  if v_req.requested_employee_id is not null and v_req.requested_employee_id <> auth.uid() then
    raise exception 'This swap request is targeted to a different employee.';
  end if;

  select *
    into v_shift
  from public.shifts s
  where s.id = v_req.shift_id
    and s.organization_id = v_org_id;

  if v_shift.id is null then
    raise exception 'Associated shift no longer exists.';
  end if;

  if v_shift.start_at <= now() then
    raise exception 'Shift has already started.';
  end if;

  update public.shift_swap_requests
  set accepted_by_employee_id = auth.uid(),
      acceptance_note = trim(coalesce(p_acceptance_note, '')),
      status = 'pending_admin',
      updated_at = now()
  where id = p_request_id;

  return p_request_id;
end;
$$;


-- Name: acknowledge_task_assignment(uuid, text); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.acknowledge_task_assignment(p_assignment_id uuid, p_note text DEFAULT ''::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_employee_id uuid;
begin
  select employee_id into v_employee_id
  from public.task_assignments
  where id = p_assignment_id;

  if v_employee_id is null then
    raise exception 'Task assignment not found.';
  end if;

  if v_employee_id <> auth.uid() then
    raise exception 'You can only acknowledge your own tasks.';
  end if;

  update public.task_assignments
  set acknowledged_at = coalesce(acknowledged_at, now()),
      acknowledged_by = auth.uid(),
      acknowledgment_note = coalesce(p_note, acknowledgment_note)
  where id = p_assignment_id;

  return true;
end;
$$;


