SET default_table_access_method = heap;

-- Name: shifts; Type: TABLE; Schema: public; Owner: -

CREATE TABLE public.shifts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    employee_id uuid,
    work_area_id uuid,
    start_at timestamp with time zone NOT NULL,
    end_at timestamp with time zone NOT NULL,
    status public.shift_status DEFAULT 'scheduled'::public.shift_status NOT NULL,
    break_minutes integer DEFAULT 30 NOT NULL,
    notes text DEFAULT ''::text NOT NULL,
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    clocked_in_at timestamp with time zone,
    clocked_out_at timestamp with time zone,
    is_unscheduled_overtime boolean DEFAULT false NOT NULL,
    organization_id uuid NOT NULL,
    worked_minutes integer,
    is_shift_pool boolean DEFAULT false NOT NULL,
    shift_pool_posted_at timestamp with time zone,
    shift_pool_posted_by uuid,
    shift_pool_claimed_at timestamp with time zone,
    shift_pool_claimed_by uuid,
    pay_multiplier numeric(5,2) DEFAULT 1.0 NOT NULL,
    clock_in_latitude double precision,
    clock_in_longitude double precision,
    clock_in_accuracy_meters double precision,
    clock_in_device text,
    clock_in_is_mobile boolean,
    CONSTRAINT shifts_break_minutes_check CHECK ((break_minutes >= 0)),
    CONSTRAINT shifts_pay_multiplier_positive CHECK ((pay_multiplier > (0)::numeric)),
    CONSTRAINT shifts_time_order CHECK ((end_at > start_at))
);


-- Name: admin_update_shift_live(uuid, uuid, uuid, timestamp with time zone, timestamp with time zone, public.shift_status, integer, text); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.admin_update_shift_live(p_shift_id uuid, p_employee_id uuid, p_work_area_id uuid DEFAULT NULL::uuid, p_start_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_status public.shift_status DEFAULT NULL::public.shift_status, p_break_minutes integer DEFAULT NULL::integer, p_notes text DEFAULT NULL::text) RETURNS public.shifts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor_org_id uuid;
  v_shift public.shifts%rowtype;
  v_employee_org_id uuid;
  v_work_area_org_id uuid;
  v_next_start timestamptz;
  v_next_end timestamptz;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required.';
  end if;

  if not public.is_admin(auth.uid()) then
    raise exception 'Only admins can update shifts in real time.';
  end if;

  v_actor_org_id := public.current_organization_id(auth.uid());
  if v_actor_org_id is null then
    raise exception 'Organization context is required.';
  end if;

  select *
    into v_shift
  from public.shifts s
  where s.id = p_shift_id
  for update;

  if v_shift.id is null then
    raise exception 'Shift not found.';
  end if;

  if v_shift.organization_id <> v_actor_org_id then
    raise exception 'Cannot update shifts across organizations.';
  end if;

  select p.organization_id
    into v_employee_org_id
  from public.profiles p
  where p.id = p_employee_id;

  if v_employee_org_id is null or v_employee_org_id <> v_actor_org_id then
    raise exception 'Employee is not in your organization.';
  end if;

  if p_work_area_id is not null then
    select wa.organization_id
      into v_work_area_org_id
    from public.work_areas wa
    where wa.id = p_work_area_id
      and wa.is_active = true;

    if v_work_area_org_id is null or v_work_area_org_id <> v_actor_org_id then
      raise exception 'Work area is not active in your organization.';
    end if;
  end if;

  v_next_start := coalesce(p_start_at, v_shift.start_at);
  v_next_end := coalesce(p_end_at, v_shift.end_at);

  if v_next_end <= v_next_start then
    raise exception 'Shift end must be after shift start.';
  end if;

  update public.shifts s
  set employee_id = p_employee_id,
      work_area_id = p_work_area_id,
      start_at = v_next_start,
      end_at = v_next_end,
      status = coalesce(p_status, s.status),
      break_minutes = greatest(coalesce(p_break_minutes, s.break_minutes, 0), 0),
      notes = coalesce(p_notes, s.notes, ''),
      is_unscheduled_overtime = false,
      updated_by = auth.uid()
  where s.id = p_shift_id
  returning * into v_shift;

  return v_shift;
end;
$$;


-- Name: apply_discipline_action(uuid, text); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.apply_discipline_action(p_action_id uuid, p_review_notes text DEFAULT ''::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_action public.discipline_actions%rowtype;
  v_next_rate numeric(10,2);
  v_days integer;
  v_start_date date;
  v_end_date date;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required.';
  end if;

  if not public.is_admin(auth.uid()) then
    raise exception 'Only admins can apply discipline actions.';
  end if;

  select *
    into v_action
  from public.discipline_actions da
  where da.id = p_action_id
  for update;

  if v_action.id is null then
    raise exception 'Discipline action not found.';
  end if;

  if not public.is_same_org(v_action.organization_id, auth.uid()) then
    raise exception 'Cannot apply discipline across organizations.';
  end if;

  if v_action.status <> 'issued' then
    raise exception 'Only issued discipline actions can be applied.';
  end if;

  if v_action.punishment_type = 'pay_rate_reduction' then
    select greatest(coalesce(p.hourly_rate, 0) - greatest(v_action.punishment_value, 0), 0)
      into v_next_rate
    from public.profiles p
    where p.id = v_action.employee_id
    for update;

    update public.profiles
    set hourly_rate = v_next_rate,
        updated_at = now()
    where id = v_action.employee_id;
  elsif v_action.punishment_type = 'unpaid_suspension' then
    v_days := greatest(1, floor(v_action.punishment_value)::integer);
    v_start_date := (now() at time zone 'utc')::date;
    v_end_date := (v_start_date + make_interval(days => v_days - 1))::date;

    insert into public.time_off_requests (
      organization_id,
      employee_id,
      start_date,
      end_date,
      request_type,
      reason,
      status,
      reviewed_by,
      reviewed_at,
      review_notes
    ) values (
      v_action.organization_id,
      v_action.employee_id,
      v_start_date,
      v_end_date,
      'unpaid',
      format('Discipline action: %s', v_action.title),
      'approved',
      auth.uid(),
      now(),
      coalesce(nullif(trim(p_review_notes), ''), 'Auto-approved unpaid suspension from discipline action')
    );
  end if;

  update public.discipline_actions
  set status = 'applied',
      reviewed_by = auth.uid(),
      reviewed_at = now(),
      review_notes = coalesce(p_review_notes, ''),
      updated_by = auth.uid()
  where id = p_action_id;

  return true;
end;
$$;


-- Name: assign_shift_break_task(uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.assign_shift_break_task(p_shift_id uuid, p_break_minutes integer DEFAULT 15, p_note text DEFAULT ''::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_employee_id uuid;
  v_start_at timestamptz;
  v_end_at timestamptz;
  v_status public.shift_status;
  v_break_minutes integer := greatest(coalesce(p_break_minutes, 15), 1);
  v_break_start timestamptz := now();
  v_break_end timestamptz;
  v_work_area_id uuid;
  v_task_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required.';
  end if;

  if not public.is_admin(auth.uid()) then
    raise exception 'Only admins can assign break tasks.';
  end if;

  select s.organization_id, s.employee_id, s.start_at, s.end_at, s.status, s.work_area_id
    into v_org_id, v_employee_id, v_start_at, v_end_at, v_status, v_work_area_id
  from public.shifts s
  where s.id = p_shift_id
  for update;

  if v_org_id is null then
    raise exception 'Shift not found.';
  end if;

  if not public.is_same_org(v_org_id, auth.uid()) then
    raise exception 'Cannot assign break tasks across organizations.';
  end if;

  if v_status = 'off_shift' then
    raise exception 'Shift is already clocked out.';
  end if;

  v_break_end := v_break_start + make_interval(mins => v_break_minutes);

  if v_break_end > v_end_at then
    v_break_end := v_end_at;
  end if;

  if v_break_end <= v_break_start then
    raise exception 'Break end must be after current time and before shift end.';
  end if;

  insert into public.tasks (
    organization_id,
    title,
    description,
    status,
    priority,
    source_system,
    start_at,
    end_at,
    work_area_id,
    shift_id,
    created_by,
    updated_by
  )
  values (
    v_org_id,
    'BREAK',
    case
      when trim(coalesce(p_note, '')) = '' then format('Auto break (%s min)', v_break_minutes)
      else trim(p_note)
    end,
    'pending',
    'normal',
    'break_auto',
    v_break_start,
    v_break_end,
    v_work_area_id,
    p_shift_id,
    auth.uid(),
    auth.uid()
  )
  returning id into v_task_id;

  insert into public.task_assignments (
    organization_id,
    task_id,
    employee_id,
    assigned_by
  )
  values (
    v_org_id,
    v_task_id,
    v_employee_id,
    auth.uid()
  );

  update public.shifts
  set status = 'break',
      clocked_out_at = coalesce(clocked_out_at, v_break_start),
      break_minutes = greatest(coalesce(break_minutes, 0), v_break_minutes),
      updated_by = auth.uid()
  where id = p_shift_id;

  insert into public.shift_break_schedules (
    organization_id,
    shift_id,
    employee_id,
    break_task_id,
    break_started_at,
    break_ends_at,
    resumed_at,
    created_by,
    updated_by
  )
  values (
    v_org_id,
    p_shift_id,
    v_employee_id,
    v_task_id,
    v_break_start,
    v_break_end,
    null,
    auth.uid(),
    auth.uid()
  )
  on conflict (shift_id) where resumed_at is null
  do update set
    break_task_id = excluded.break_task_id,
    break_started_at = excluded.break_started_at,
    break_ends_at = excluded.break_ends_at,
    updated_by = auth.uid(),
    resumed_at = null;

  return v_task_id;
end;
$$;


-- Name: assign_task_to_employee(uuid, text, text, timestamp with time zone, timestamp with time zone, uuid, uuid, public.task_priority); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.assign_task_to_employee(p_employee_id uuid, p_title text, p_description text, p_start_at timestamp with time zone, p_end_at timestamp with time zone, p_work_area_id uuid DEFAULT NULL::uuid, p_shift_id uuid DEFAULT NULL::uuid, p_priority public.task_priority DEFAULT 'normal'::public.task_priority) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_task_id uuid;
  v_actor_org_id uuid;
  v_employee_org_id uuid;
begin
  if not public.is_admin(auth.uid()) then
    raise exception 'Only admins can assign tasks.';
  end if;

  v_actor_org_id := public.current_organization_id(auth.uid());

  select p.organization_id
    into v_employee_org_id
  from public.profiles p
  where p.id = p_employee_id;

  if v_actor_org_id is null then
    raise exception 'Actor organization could not be resolved.';
  end if;

  if v_employee_org_id is null or v_employee_org_id <> v_actor_org_id then
    raise exception 'Cannot assign tasks across organizations.';
  end if;

  insert into public.tasks (
    organization_id,
    title,
    description,
    status,
    priority,
    start_at,
    end_at,
    work_area_id,
    shift_id,
    created_by,
    updated_by
  )
  values (
    v_actor_org_id,
    p_title,
    coalesce(p_description, ''),
    'pending',
    coalesce(p_priority, 'normal'),
    p_start_at,
    p_end_at,
    p_work_area_id,
    p_shift_id,
    auth.uid(),
    auth.uid()
  )
  returning id into v_task_id;

  insert into public.task_assignments (organization_id, task_id, employee_id, assigned_by)
  values (v_actor_org_id, v_task_id, p_employee_id, auth.uid());

  return v_task_id;
end;
$$;


-- Name: training_assignments; Type: TABLE; Schema: public; Owner: -

CREATE TABLE public.training_assignments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    course_id uuid NOT NULL,
    employee_id uuid NOT NULL,
    assigned_by uuid,
    assigned_at timestamp with time zone DEFAULT now() NOT NULL,
    due_at timestamp with time zone,
    status text DEFAULT 'assigned'::text NOT NULL,
    completed_at timestamp with time zone,
    completion_notes text DEFAULT ''::text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT training_assignments_status_check CHECK ((status = ANY (ARRAY['assigned'::text, 'in_progress'::text, 'completed'::text])))
);


-- Name: assign_training_course(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.assign_training_course(p_course_id uuid, p_employee_id uuid, p_due_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS public.training_assignments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_course_org_id uuid;
  v_employee_org_id uuid;
  v_row public.training_assignments%rowtype;
begin
  if not (public.is_admin(auth.uid()) or public.is_training_manager(auth.uid())) then
    raise exception 'Only admins or training managers can assign trainings.';
  end if;

  v_org_id := public.current_organization_id(auth.uid());
  if v_org_id is null then
    raise exception 'Organization context is required.';
  end if;

  select organization_id into v_course_org_id
  from public.training_courses
  where id = p_course_id;

  if v_course_org_id is null then
    raise exception 'Training course not found.';
  end if;

  if v_course_org_id <> v_org_id then
    raise exception 'Training course is not in your organization.';
  end if;

  select organization_id into v_employee_org_id
  from public.profiles
  where id = p_employee_id
    and role = 'employee';

  if v_employee_org_id is null then
    raise exception 'Employee not found.';
  end if;

  if v_employee_org_id <> v_org_id then
    raise exception 'Employee is not in your organization.';
  end if;

  insert into public.training_assignments (
    organization_id,
    course_id,
    employee_id,
    assigned_by,
    assigned_at,
    due_at,
    status,
    completion_notes
  )
  values (
    v_org_id,
    p_course_id,
    p_employee_id,
    auth.uid(),
    now(),
    p_due_at,
    'assigned',
    ''
  )
  on conflict (course_id, employee_id)
  do update set
    assigned_by = excluded.assigned_by,
    assigned_at = now(),
    due_at = excluded.due_at,
    status = case when public.training_assignments.status = 'completed' then 'completed' else 'assigned' end,
    completed_at = case when public.training_assignments.status = 'completed' then public.training_assignments.completed_at else null end,
    completion_notes = case when public.training_assignments.status = 'completed' then public.training_assignments.completion_notes else '' end,
    updated_at = now()
  returning * into v_row;

  return v_row;
end;
$$;


-- Name: calculate_shift_paid_minutes(timestamp with time zone, timestamp with time zone, timestamp with time zone, integer, integer); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.calculate_shift_paid_minutes(p_clocked_in timestamp with time zone, p_clocked_out timestamp with time zone, p_scheduled_start timestamp with time zone, p_break_minutes integer DEFAULT 0, p_buffer_minutes integer DEFAULT 5) RETURNS integer
    LANGUAGE plpgsql IMMUTABLE
    AS $$
declare
  v_paid_start timestamptz;
  v_buffer_start timestamptz;
  v_minutes integer;
begin
  if p_clocked_in is null or p_clocked_out is null then
    return null;
  end if;

  v_paid_start := p_clocked_in;

  if p_scheduled_start is not null then
    v_buffer_start := p_scheduled_start - make_interval(mins => greatest(coalesce(p_buffer_minutes, 0), 0));
    if p_clocked_in < v_buffer_start then
      v_paid_start := p_scheduled_start;
    end if;
  end if;

  v_minutes := floor(extract(epoch from (p_clocked_out - v_paid_start)) / 60.0)::integer
    - greatest(coalesce(p_break_minutes, 0), 0);

  return greatest(v_minutes, 0);
end;
$$;


-- Name: calculate_shift_unpaid_early_minutes(timestamp with time zone, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.calculate_shift_unpaid_early_minutes(p_clocked_in timestamp with time zone, p_scheduled_start timestamp with time zone, p_buffer_minutes integer DEFAULT 5) RETURNS integer
    LANGUAGE plpgsql IMMUTABLE
    AS $$
declare
  v_buffer_start timestamptz;
  v_minutes integer;
begin
  if p_clocked_in is null or p_scheduled_start is null then
    return 0;
  end if;

  v_buffer_start := p_scheduled_start - make_interval(mins => greatest(coalesce(p_buffer_minutes, 0), 0));

  if p_clocked_in >= v_buffer_start then
    return 0;
  end if;

  v_minutes := floor(extract(epoch from (p_scheduled_start - p_clocked_in)) / 60.0)::integer;
  return greatest(v_minutes, 0);
end;
$$;


-- Name: calculate_shift_worked_minutes(timestamp with time zone, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.calculate_shift_worked_minutes(p_start timestamp with time zone, p_end timestamp with time zone, p_break_minutes integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql IMMUTABLE
    AS $$
declare
  v_minutes integer;
begin
  if p_start is null or p_end is null then
    return null;
  end if;

  v_minutes := floor(extract(epoch from (p_end - p_start)) / 60.0)::integer
    - greatest(coalesce(p_break_minutes, 0), 0);

  return greatest(v_minutes, 0);
end;
$$;


-- Name: claim_shift_pool_shift(uuid); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.claim_shift_pool_shift(p_shift_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_current_employee_id uuid;
  v_status public.shift_status;
  v_is_shift_pool boolean;
  v_clocked_in_at timestamptz;
  v_start_at timestamptz;
  v_end_at timestamptz;
  v_break_minutes integer;
  v_max_weekly_hours integer;
  v_week_start timestamptz;
  v_week_end timestamptz;
  v_current_week_minutes integer;
  v_new_shift_minutes integer;
begin
  select organization_id, employee_id, status, coalesce(is_shift_pool, false), clocked_in_at, start_at, end_at, break_minutes
    into v_org_id, v_current_employee_id, v_status, v_is_shift_pool, v_clocked_in_at, v_start_at, v_end_at, v_break_minutes
  from public.shifts
  where id = p_shift_id
  for update;

  if v_org_id is null then
    raise exception 'Shift not found.';
  end if;

  if auth.uid() is null then
    raise exception 'Authentication is required.';
  end if;

  if not public.is_same_org(v_org_id, auth.uid()) then
    raise exception 'Cannot claim shifts across organizations.';
  end if;

  if not v_is_shift_pool then
    raise exception 'Shift is not currently in the shift pool.';
  end if;

  if v_status <> 'scheduled' then
    raise exception 'Only scheduled shifts can be claimed from the shift pool.';
  end if;

  if v_clocked_in_at is not null then
    raise exception 'Shift is already in progress.';
  end if;

  if v_end_at <= now() then
    raise exception 'Shift has already ended.';
  end if;

  if v_current_employee_id = auth.uid() then
    raise exception 'This shift is already assigned to you.';
  end if;

  if exists (
    select 1
    from public.shifts s
    where s.employee_id = auth.uid()
      and s.id <> p_shift_id
      and s.organization_id = v_org_id
      and s.start_at < v_end_at
      and s.end_at > v_start_at
      and s.status <> 'off_shift'
  ) then
    raise exception 'You already have an overlapping shift.';
  end if;

  select ewp.max_weekly_hours
    into v_max_weekly_hours
  from public.employee_work_preferences ewp
  where ewp.employee_id = auth.uid()
    and ewp.organization_id = v_org_id;

  if v_max_weekly_hours is not null then
    v_week_start := date_trunc('week', v_start_at);
    v_week_end := v_week_start + interval '7 days';
    v_new_shift_minutes := greatest(
      0,
      (extract(epoch from (v_end_at - v_start_at)) / 60)::integer - greatest(coalesce(v_break_minutes, 0), 0)
    );

    select coalesce(sum(greatest(0, (extract(epoch from (s.end_at - s.start_at)) / 60)::integer - greatest(coalesce(s.break_minutes, 0), 0))), 0)
      into v_current_week_minutes
    from public.shifts s
    where s.employee_id = auth.uid()
      and s.organization_id = v_org_id
      and s.id <> p_shift_id
      and s.start_at >= v_week_start
      and s.start_at < v_week_end
      and s.status <> 'off_shift';

    if v_current_week_minutes + v_new_shift_minutes > v_max_weekly_hours * 60 then
      raise exception 'Claim exceeds your max weekly hours preference.';
    end if;
  end if;

  update public.shifts
  set employee_id = auth.uid(),
      is_shift_pool = false,
      shift_pool_posted_at = null,
      shift_pool_posted_by = null,
      shift_pool_claimed_at = now(),
      shift_pool_claimed_by = auth.uid(),
      updated_by = auth.uid()
  where id = p_shift_id;

  insert into public.app_notifications (
    organization_id,
    recipient_id,
    actor_id,
    category,
    title,
    body,
    payload
  )
  values (
    v_org_id,
    auth.uid(),
    auth.uid(),
    'shift_pool_claimed',
    'Shift Claimed',
    'You successfully claimed a shift from the pool.',
    jsonb_build_object('shift_id', p_shift_id)
  );

  return true;
end;
$$;


-- Name: clock_in_shift(uuid); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.clock_in_shift(p_shift_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  return public.clock_in_shift(p_shift_id, null, null, null, null, null);
end;
$$;


-- Name: clock_in_shift(uuid, double precision, double precision, double precision, text, boolean); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.clock_in_shift(p_shift_id uuid, p_latitude double precision, p_longitude double precision, p_accuracy_meters double precision, p_device text, p_is_mobile boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_employee_id uuid;
  v_status public.shift_status;
  v_unscheduled boolean;
  v_now timestamptz := now();
begin
  select employee_id, status, coalesce(is_unscheduled_overtime, false)
    into v_employee_id, v_status, v_unscheduled
  from public.shifts
  where id = p_shift_id;

  if v_employee_id is null then
    raise exception 'Shift not found.';
  end if;

  if v_employee_id <> auth.uid() then
    raise exception 'You can only clock in for your own shift.';
  end if;

  if v_unscheduled then
    raise exception 'Use unscheduled overtime clock-in for unscheduled overtime shifts.';
  end if;

  if v_status = 'off_shift' then
    raise exception 'Cannot clock in to an off-shift record.';
  end if;

  if exists (
    select 1
    from public.shifts s
    where s.employee_id = auth.uid()
      and s.clocked_in_at is not null
      and s.clocked_out_at is null
      and s.status <> 'off_shift'
      and coalesce(s.is_unscheduled_overtime, false) = false
      and public.is_same_org(s.organization_id, auth.uid())
  ) then
    return true;
  end if;

  update public.shifts
  set status = 'on_duty',
      clocked_in_at = coalesce(clocked_in_at, v_now),
      clocked_out_at = null,
      clock_in_latitude = coalesce(p_latitude, clock_in_latitude),
      clock_in_longitude = coalesce(p_longitude, clock_in_longitude),
      clock_in_accuracy_meters = coalesce(greatest(coalesce(p_accuracy_meters, 0), 0), clock_in_accuracy_meters),
      clock_in_device = coalesce(nullif(trim(coalesce(p_device, '')), ''), clock_in_device),
      clock_in_is_mobile = coalesce(p_is_mobile, clock_in_is_mobile),
      updated_by = auth.uid()
  where id = p_shift_id;

  return true;
end;
$$;


-- Name: clock_in_unscheduled_shift(text); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.clock_in_unscheduled_shift(p_note text DEFAULT ''::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  return public.clock_in_unscheduled_shift(p_note, null, null, null, null, null);
end;
$$;


-- Name: clock_in_unscheduled_shift(text, double precision, double precision, double precision, text, boolean); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.clock_in_unscheduled_shift(p_note text, p_latitude double precision, p_longitude double precision, p_accuracy_meters double precision, p_device text, p_is_mobile boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_now timestamptz := now();
  v_shift_id uuid;
begin
  if exists (
    select 1
    from public.shifts s
    where s.employee_id = auth.uid()
      and s.start_at <= v_now
      and s.end_at >= v_now
      and s.status <> 'off_shift'
      and coalesce(s.is_unscheduled_overtime, false) = false
  ) then
    raise exception 'You are currently on a scheduled shift. Clock into your scheduled shift instead.';
  end if;

  if exists (
    select 1
    from public.shifts s
    where s.employee_id = auth.uid()
      and coalesce(s.is_unscheduled_overtime, false) = true
      and s.clocked_out_at is null
      and s.status <> 'off_shift'
  ) then
    raise exception 'You already have an active unscheduled overtime shift.';
  end if;

  insert into public.shifts (
    employee_id,
    work_area_id,
    start_at,
    end_at,
    status,
    clocked_in_at,
    clocked_out_at,
    clock_in_latitude,
    clock_in_longitude,
    clock_in_accuracy_meters,
    clock_in_device,
    clock_in_is_mobile,
    is_unscheduled_overtime,
    pay_multiplier,
    break_minutes,
    notes,
    created_by,
    updated_by
  )
  values (
    auth.uid(),
    null,
    v_now,
    v_now + interval '12 hours',
    'on_duty',
    v_now,
    null,
    p_latitude,
    p_longitude,
    greatest(coalesce(p_accuracy_meters, 0), 0),
    nullif(trim(coalesce(p_device, '')), ''),
    p_is_mobile,
    true,
    1.5,
    0,
    case
      when trim(coalesce(p_note, '')) = '' then 'Unscheduled overtime'
      else trim(p_note)
    end,
    auth.uid(),
    auth.uid()
  )
  returning id into v_shift_id;

  return v_shift_id;
end;
$$;


-- Name: clock_out_shift(uuid); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.clock_out_shift(p_shift_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_employee_id uuid;
  v_status public.shift_status;
  v_unscheduled boolean;
  v_now timestamptz := now();
  v_punch_shift_id uuid;
  v_punch_start timestamptz;
begin
  select employee_id, status, coalesce(is_unscheduled_overtime, false)
    into v_employee_id, v_status, v_unscheduled
  from public.shifts
  where id = p_shift_id;

  if v_employee_id is null then
    raise exception 'Shift not found.';
  end if;

  if v_employee_id <> auth.uid() then
    raise exception 'You can only clock out for your own shift.';
  end if;

  -- Preserve unscheduled overtime clock-out semantics.
  if v_unscheduled then
    if v_status = 'off_shift' then
      raise exception 'Shift is already clocked out.';
    end if;

    update public.shifts
    set status = 'off_shift',
        clocked_out_at = coalesce(clocked_out_at, v_now),
        end_at = greatest(start_at, v_now),
        updated_by = auth.uid()
    where id = p_shift_id;

    return true;
  end if;

  -- Find the active punch (the shift the employee clocked in on).
  select s.id, s.clocked_in_at
    into v_punch_shift_id, v_punch_start
  from public.shifts s
  where s.employee_id = auth.uid()
    and s.clocked_in_at is not null
    and s.clocked_out_at is null
    and s.status <> 'off_shift'
    and coalesce(s.is_unscheduled_overtime, false) = false
    and public.is_same_org(s.organization_id, auth.uid())
  order by s.clocked_in_at asc
  limit 1;

  if v_punch_shift_id is null or v_punch_start is null then
    raise exception 'No active clock-in found.';
  end if;

  -- Backfill clock windows for every overlapping scheduled shift on this punch.
  update public.shifts s
  set status = 'off_shift',
      clocked_in_at = case
        when s.clocked_in_at is not null then s.clocked_in_at
        when s.id = v_punch_shift_id then v_punch_start
        else greatest(s.start_at, v_punch_start)
      end,
      clocked_out_at = case
        when s.clocked_out_at is not null then s.clocked_out_at
        else least(s.end_at, v_now)
      end,
      updated_by = auth.uid()
  where s.employee_id = auth.uid()
    and public.is_same_org(s.organization_id, auth.uid())
    and coalesce(s.is_unscheduled_overtime, false) = false
    and s.start_at < v_now
    and s.end_at > v_punch_start;

  return true;
end;
$$;


-- Name: complete_training_assignment(uuid, text); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.complete_training_assignment(p_assignment_id uuid, p_completion_notes text DEFAULT ''::text) RETURNS public.training_assignments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_row public.training_assignments%rowtype;
begin
  v_org_id := public.current_organization_id(auth.uid());
  if v_org_id is null then
    raise exception 'Organization context is required.';
  end if;

  update public.training_assignments a
  set status = 'completed',
      completed_at = now(),
      completion_notes = coalesce(p_completion_notes, ''),
      updated_at = now()
  where a.id = p_assignment_id
    and a.organization_id = v_org_id
    and a.employee_id = auth.uid()
  returning a.* into v_row;

  if v_row.id is null then
    raise exception 'Training assignment not found for this employee.';
  end if;

  return v_row;
end;
$$;


-- Name: create_or_assign_overtime_request(uuid, timestamp with time zone, timestamp with time zone, text, public.overtime_request_type); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.create_or_assign_overtime_request(p_employee_id uuid, p_start_at timestamp with time zone, p_end_at timestamp with time zone, p_note text DEFAULT ''::text, p_overtime_type public.overtime_request_type DEFAULT 'voluntary'::public.overtime_request_type) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_request_id uuid;
  v_auto_approve boolean := false;
  v_actor_is_admin boolean := false;
begin
  if p_start_at is null or p_end_at is null or p_end_at <= p_start_at then
    raise exception 'Invalid overtime window.';
  end if;

  v_org_id := public.current_organization_id(auth.uid());
  if v_org_id is null then
    raise exception 'Organization context is required.';
  end if;

  if not exists (
    select 1
    from public.profiles p
    where p.id = p_employee_id
      and p.organization_id = v_org_id
  ) then
    raise exception 'Employee not found in current organization.';
  end if;

  select exists (
    select 1
    from public.profiles p
    where p.id = auth.uid()
      and p.organization_id = v_org_id
      and p.role = 'admin'::public.app_role
  )
  into v_actor_is_admin;

  if p_employee_id <> auth.uid() and not v_actor_is_admin then
    raise exception 'Only admins can assign overtime to other employees.';
  end if;

  if p_overtime_type = 'mandatory' and not v_actor_is_admin then
    raise exception 'Only admins can assign mandatory overtime.';
  end if;

  v_auto_approve := p_overtime_type = 'mandatory' and v_actor_is_admin;

  insert into public.overtime_requests (
    employee_id,
    start_at,
    end_at,
    status,
    overtime_type,
    assigned_by,
    note,
    organization_id
  )
  values (
    p_employee_id,
    p_start_at,
    p_end_at,
    'pending',
    p_overtime_type,
    case when v_actor_is_admin and p_employee_id <> auth.uid() then auth.uid() else null end,
    trim(coalesce(p_note, '')),
    v_org_id
  )
  returning id into v_request_id;

  if v_auto_approve then
    perform public.review_overtime_request(
      v_request_id,
      'approved'::public.overtime_request_status,
      'Mandatory overtime assigned by admin.'
    );
  end if;

  return v_request_id;
end;
$$;


-- Name: create_shift_swap_request(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.create_shift_swap_request(p_shift_id uuid, p_requested_employee_id uuid DEFAULT NULL::uuid, p_request_note text DEFAULT ''::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_shift public.shifts%rowtype;
  v_request_id uuid;
begin
  v_org_id := public.current_organization_id(auth.uid());
  if v_org_id is null then
    raise exception 'Organization context is required.';
  end if;

  select *
    into v_shift
  from public.shifts s
  where s.id = p_shift_id
    and s.organization_id = v_org_id;

  if v_shift.id is null then
    raise exception 'Shift not found.';
  end if;

  if v_shift.employee_id is distinct from auth.uid() then
    raise exception 'You can only request swaps for your own shift.';
  end if;

  if v_shift.status <> 'scheduled' then
    raise exception 'Only scheduled shifts can be swapped.';
  end if;

  if v_shift.start_at <= now() then
    raise exception 'Shift swaps must be requested before shift start.';
  end if;

  insert into public.shift_swap_requests (
    organization_id,
    shift_id,
    requester_id,
    requested_employee_id,
    status,
    request_note
  )
  values (
    v_org_id,
    p_shift_id,
    auth.uid(),
    p_requested_employee_id,
    'open',
    trim(coalesce(p_request_note, ''))
  )
  returning id into v_request_id;

  return v_request_id;
end;
$$;


-- Name: training_courses; Type: TABLE; Schema: public; Owner: -

CREATE TABLE public.training_courses (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    title text NOT NULL,
    description text DEFAULT ''::text NOT NULL,
    content text DEFAULT ''::text NOT NULL,
    estimated_minutes integer DEFAULT 15 NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT training_courses_estimated_minutes_check CHECK ((estimated_minutes > 0))
);


-- Name: create_training_course(text, text, text, integer, boolean); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.create_training_course(p_title text, p_description text DEFAULT ''::text, p_content text DEFAULT ''::text, p_estimated_minutes integer DEFAULT 15, p_is_active boolean DEFAULT true) RETURNS public.training_courses
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_row public.training_courses%rowtype;
  v_title text;
begin
  if not (public.is_admin(auth.uid()) or public.is_training_manager(auth.uid())) then
    raise exception 'Only admins or training managers can create trainings.';
  end if;

  v_org_id := public.current_organization_id(auth.uid());
  if v_org_id is null then
    raise exception 'Organization context is required.';
  end if;

  v_title := trim(coalesce(p_title, ''));
  if v_title = '' then
    raise exception 'Training title is required.';
  end if;

  insert into public.training_courses (
    organization_id,
    title,
    description,
    content,
    estimated_minutes,
    is_active,
    created_by,
    updated_by
  )
  values (
    v_org_id,
    v_title,
    coalesce(p_description, ''),
    coalesce(p_content, ''),
    greatest(coalesce(p_estimated_minutes, 15), 1),
    coalesce(p_is_active, true),
    auth.uid(),
    auth.uid()
  )
  returning * into v_row;

  return v_row;
end;
$$;


-- Name: current_organization_id(uuid); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.current_organization_id(p_user_id uuid DEFAULT auth.uid()) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select p.organization_id
  from public.profiles p
  where p.id = p_user_id
  limit 1
$$;


-- Name: employee_has_covering_shift(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.employee_has_covering_shift(p_employee_id uuid, p_start_at timestamp with time zone, p_end_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.shifts s
    where s.employee_id = p_employee_id
      and s.start_at <= p_start_at
      and s.end_at >= p_end_at
      and public.is_same_org(s.organization_id, auth.uid())
  );
$$;


-- Name: employee_message_admin_recipients(uuid); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.employee_message_admin_recipients(p_organization_id uuid) RETURNS TABLE(id uuid, full_name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select p.id, p.full_name
  from public.profiles p
  where p.organization_id = p_organization_id
    and p.id <> auth.uid()
    and public.is_same_org(p_organization_id, auth.uid())
    and (
      p.role = 'admin'::public.app_role
      or coalesce(p.is_training_manager, false) = true
      or public.has_operator_shift_access(p.id)
      or public.has_management_shift_access(p.id)
    )
  order by
    case
      when p.role = 'admin'::public.app_role then 0
      when coalesce(p.is_training_manager, false) = true then 1
      else 2
    end,
    p.full_name asc;
$$;


-- Name: employee_message_thread_key(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.employee_message_thread_key(p_user_a uuid, p_user_b uuid) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case
    when p_user_a is null or p_user_b is null then null
    when p_user_a::text <= p_user_b::text then p_user_a::text || ':' || p_user_b::text
    else p_user_b::text || ':' || p_user_a::text
  end
$$;


-- Name: enforce_actor_organization(); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.enforce_actor_organization() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor_org_id uuid;
begin
  v_actor_org_id := public.current_organization_id(auth.uid());

  if new.organization_id is null then
    new.organization_id := v_actor_org_id;
  end if;

  if v_actor_org_id is not null and new.organization_id <> v_actor_org_id then
    raise exception 'Cross-organization write is not allowed.';
  end if;

  return new;
end;
$$;


-- Name: enqueue_my_shift_start_notifications(integer); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.enqueue_my_shift_start_notifications(p_lookahead_minutes integer DEFAULT 30) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_window_minutes integer := greatest(5, least(coalesce(p_lookahead_minutes, 30), 240));
  v_inserted integer := 0;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required.';
  end if;

  v_org_id := public.current_organization_id(auth.uid());
  if v_org_id is null then
    raise exception 'Organization context is required.';
  end if;

  with upcoming as (
    select
      s.id,
      s.start_at,
      s.end_at,
      s.work_area_id,
      wa.name as work_area_name,
      greatest(1, ceil(extract(epoch from (s.start_at - now())) / 60.0)::integer) as minutes_until_start
    from public.shifts s
    left join public.work_areas wa on wa.id = s.work_area_id
    where s.organization_id = v_org_id
      and s.employee_id = auth.uid()
      and s.status in ('scheduled', 'on_duty', 'break')
      and s.start_at > now()
      and s.start_at <= now() + make_interval(mins => v_window_minutes)
  ), inserted as (
    insert into public.app_notifications (
      organization_id,
      recipient_id,
      actor_id,
      category,
      title,
      body,
      payload
    )
    select
      v_org_id,
      auth.uid(),
      null,
      'shift_starting_soon',
      'Shift Starting Soon',
      format(
        'Your shift starts in %s min at %s%s.',
        u.minutes_until_start,
        to_char(u.start_at, 'HH24:MI'),
        case when coalesce(trim(u.work_area_name), '') <> '' then format(' (%s)', trim(u.work_area_name)) else '' end
      ),
      jsonb_build_object(
        'shift_id', u.id,
        'start_at', u.start_at,
        'end_at', u.end_at,
        'minutes_until_start', u.minutes_until_start,
        'work_area_id', u.work_area_id,
        'work_area_name', coalesce(u.work_area_name, '')
      )
    from upcoming u
    where not exists (
      select 1
      from public.app_notifications n
      where n.organization_id = v_org_id
        and n.recipient_id = auth.uid()
        and n.category = 'shift_starting_soon'
        and n.payload ->> 'shift_id' = u.id::text
        and n.created_at >= now() - interval '12 hours'
    )
    returning 1
  )
  select count(*)::integer into v_inserted
  from inserted;

  return v_inserted;
end;
$$;


-- Name: fetch_shift_intelligence(date, integer); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.fetch_shift_intelligence(p_date date DEFAULT CURRENT_DATE, p_horizon_days integer DEFAULT 7) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_horizon integer := greatest(1, least(30, coalesce(p_horizon_days, 7)));
  v_result jsonb;
begin
  v_org_id := public.current_organization_id(auth.uid());
  if v_org_id is null then
    raise exception 'Organization context is required.';
  end if;

  with fatigue as (
    select coalesce(jsonb_agg(row_to_json(f) order by f.fatigue_score desc), '[]'::jsonb) as rows
    from (
      select
        p.id as employee_id,
        coalesce(nullif(p.full_name, ''), p.email) as employee_name,
        round((
          coalesce(sum(
            greatest(0, extract(epoch from (least(s.end_at, now()) - greatest(s.start_at, now() - interval '7 days'))) / 3600.0)
          ), 0) * 1.6
          + coalesce(sum(case when s.start_at::time >= time '22:00' or s.end_at::time <= time '06:00' then 8 else 0 end), 0)
          + coalesce(max(case when s.status in ('on_duty', 'break') then 10 else 0 end), 0)
        )::numeric, 2) as fatigue_score,
        coalesce(count(s.*), 0)::integer as shifts_7d
      from public.profiles p
      left join public.shifts s
        on s.organization_id = v_org_id
       and s.employee_id = p.id
       and s.start_at >= now() - interval '7 days'
      where p.organization_id = v_org_id
        and p.role = 'employee'::public.app_role
      group by p.id, p.full_name, p.email
      order by fatigue_score desc
      limit 25
    ) f
  ), overtime_forecast as (
    select coalesce(jsonb_agg(row_to_json(o) order by o.projected_overtime_hours desc), '[]'::jsonb) as rows
    from (
      select
        p.id as employee_id,
        coalesce(nullif(p.full_name, ''), p.email) as employee_name,
        round(greatest(0, (coalesce(sum(extract(epoch from (s.end_at - s.start_at)) / 3600.0), 0) - coalesce(ewp.max_weekly_hours, 40)))::numeric, 2) as projected_overtime_hours,
        round(coalesce(sum(extract(epoch from (s.end_at - s.start_at)) / 3600.0), 0)::numeric, 2) as scheduled_hours_horizon,
        coalesce(ewp.max_weekly_hours, 40) as weekly_limit_hours
      from public.profiles p
      left join public.employee_work_preferences ewp
        on ewp.organization_id = v_org_id
       and ewp.employee_id = p.id
      left join public.shifts s
        on s.organization_id = v_org_id
       and s.employee_id = p.id
       and s.start_at::date >= p_date
       and s.start_at::date < p_date + make_interval(days => v_horizon)
      where p.organization_id = v_org_id
        and p.role = 'employee'::public.app_role
      group by p.id, p.full_name, p.email, ewp.max_weekly_hours
      order by projected_overtime_hours desc
      limit 25
    ) o
  ), staffing_gaps as (
    select coalesce(jsonb_agg(row_to_json(g) order by g.day_date, g.work_area_name), '[]'::jsonb) as rows
    from (
      with day_series as (
        select generate_series(p_date, p_date + make_interval(days => v_horizon - 1), interval '1 day')::date as d
      )
      select
        ds.d as day_date,
        wa.id as work_area_id,
        wa.name as work_area_name,
        coalesce(count(s.*), 0)::integer as scheduled_count,
        greatest(1, (
          select coalesce(round(avg(day_count))::integer, 1)
          from (
            select count(*)::numeric as day_count
            from public.shifts hist
            where hist.organization_id = v_org_id
              and hist.work_area_id = wa.id
              and hist.start_at::date >= p_date - interval '21 days'
              and hist.start_at::date < p_date
            group by hist.start_at::date
          ) h
        )) as target_count,
        greatest(0, greatest(1, (
          select coalesce(round(avg(day_count))::integer, 1)
          from (
            select count(*)::numeric as day_count
            from public.shifts hist
            where hist.organization_id = v_org_id
              and hist.work_area_id = wa.id
              and hist.start_at::date >= p_date - interval '21 days'
              and hist.start_at::date < p_date
            group by hist.start_at::date
          ) h
        )) - coalesce(count(s.*), 0))::integer as gap_count
      from day_series ds
      cross join public.work_areas wa
      left join public.shifts s
        on s.organization_id = v_org_id
       and s.work_area_id = wa.id
       and s.start_at::date = ds.d
      where wa.is_active = true
      group by ds.d, wa.id, wa.name
      having greatest(0, greatest(1, (
        select coalesce(round(avg(day_count))::integer, 1)
        from (
          select count(*)::numeric as day_count
          from public.shifts hist
          where hist.organization_id = v_org_id
            and hist.work_area_id = wa.id
            and hist.start_at::date >= p_date - interval '21 days'
            and hist.start_at::date < p_date
          group by hist.start_at::date
        ) h
      )) - coalesce(count(s.*), 0)) > 0
      order by ds.d, wa.name
      limit 120
    ) g
  ), cover_now as (
    select coalesce(jsonb_agg(row_to_json(c) order by c.preference_match desc, c.current_week_hours asc), '[]'::jsonb) as rows
    from (
      select
        p.id as employee_id,
        coalesce(nullif(p.full_name, ''), p.email) as employee_name,
        coalesce(wa.name, 'Unassigned') as preferred_area,
        case when ewp.preferred_work_area_ids is not null and coalesce(array_length(ewp.preferred_work_area_ids, 1), 0) > 0 then true else false end as preference_match,
        round(coalesce((
          select sum(extract(epoch from (s2.end_at - s2.start_at)) / 3600.0)
          from public.shifts s2
          where s2.organization_id = v_org_id
            and s2.employee_id = p.id
            and s2.start_at::date >= date_trunc('week', now())::date
            and s2.start_at::date < date_trunc('week', now())::date + interval '7 days'
        ), 0)::numeric, 2) as current_week_hours
      from public.profiles p
      left join public.employee_work_preferences ewp
        on ewp.organization_id = v_org_id
       and ewp.employee_id = p.id
      left join public.work_areas wa
        on wa.id = (ewp.preferred_work_area_ids)[1]
      where p.organization_id = v_org_id
        and p.role = 'employee'::public.app_role
        and not exists (
          select 1
          from public.shifts s
          where s.organization_id = v_org_id
            and s.employee_id = p.id
            and s.start_at <= now()
            and s.end_at >= now()
            and s.status in ('scheduled', 'on_duty', 'break')
        )
      order by preference_match desc, current_week_hours asc
      limit 15
    ) c
  )
  select jsonb_build_object(
    'generated_at', now(),
    'fatigue_risk', (select rows from fatigue),
    'overtime_forecast', (select rows from overtime_forecast),
    'staffing_gaps', (select rows from staffing_gaps),
    'cover_now_suggestions', (select rows from cover_now)
  )
  into v_result;

  return coalesce(v_result, '{}'::jsonb);
end;
$$;


-- Name: has_management_shift_access(uuid); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.has_management_shift_access(user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.shifts s
    join public.work_areas wa
      on wa.id = s.work_area_id
     and wa.organization_id = s.organization_id
    where s.employee_id = user_id
      and public.is_same_org(s.organization_id, user_id)
      and lower(trim(wa.name)) = 'management'
      and s.status in ('scheduled', 'on_duty', 'break')
      and (s.start_at at time zone 'utc')::date <= (now() at time zone 'utc')::date
      and (s.end_at at time zone 'utc')::date >= (now() at time zone 'utc')::date
  );
$$;


-- Name: has_operator_shift_access(uuid); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.has_operator_shift_access(user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.shifts s
    join public.work_areas wa
      on wa.id = s.work_area_id
     and wa.organization_id = s.organization_id
    where s.employee_id = user_id
      and s.clocked_in_at is not null
      and s.clocked_out_at is null
      and s.status <> 'off_shift'
      and public.is_same_org(s.organization_id, user_id)
      and lower(wa.name) = 'operator'
  );
$$;


-- Name: is_admin(uuid); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.is_admin(user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.profiles p
    where p.id = user_id
      and p.organization_id is not null
      and p.role = 'admin'::public.app_role
  )
  or public.has_operator_shift_access(user_id)
  or public.has_management_shift_access(user_id);
$$;


-- Name: is_same_org(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.is_same_org(p_org_id uuid, p_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select p_org_id is not null
     and p_org_id = public.current_organization_id(p_user_id)
$$;


-- Name: is_training_manager(uuid); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.is_training_manager(user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.profiles p
    where p.id = user_id
      and p.organization_id = public.current_organization_id(user_id)
      and p.is_training_manager = true
  );
$$;


-- Name: list_employee_message_thread_messages(uuid, integer); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.list_employee_message_thread_messages(p_counterparty_id uuid, p_limit integer DEFAULT 200) RETURNS TABLE(id uuid, organization_id uuid, sender_id uuid, recipient_id uuid, subject text, message text, read_at timestamp with time zone, created_at timestamp with time zone, thread_key text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_thread_key text;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required.';
  end if;

  v_org_id := public.current_organization_id(auth.uid());
  if v_org_id is null then
    raise exception 'Organization context is required.';
  end if;

  if p_counterparty_id is null or p_counterparty_id = auth.uid() then
    raise exception 'Counterparty is required.';
  end if;

  if not exists (
    select 1
    from public.profiles p
    where p.id = p_counterparty_id
      and p.organization_id = v_org_id
  ) then
    raise exception 'Counterparty must be in your organization.';
  end if;

  v_thread_key := public.employee_message_thread_key(auth.uid(), p_counterparty_id);

  return query
  select
    m.id,
    m.organization_id,
    m.sender_id,
    m.recipient_id,
    m.subject,
    m.message,
    m.read_at,
    m.created_at,
    m.thread_key
  from public.employee_messages m
  where m.organization_id = v_org_id
    and m.thread_key = v_thread_key
  order by m.created_at desc
  limit greatest(coalesce(p_limit, 200), 1);
end;
$$;


-- Name: list_employee_message_threads(integer); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.list_employee_message_threads(p_limit integer DEFAULT 100) RETURNS TABLE(thread_key text, counterparty_id uuid, counterparty_name text, last_message text, last_subject text, last_created_at timestamp with time zone, unread_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required.';
  end if;

  v_org_id := public.current_organization_id(auth.uid());
  if v_org_id is null then
    raise exception 'Organization context is required.';
  end if;

  return query
  with scoped as (
    select
      m.*,
      case when m.sender_id = auth.uid() then m.recipient_id else m.sender_id end as cp_id
    from public.employee_messages m
    where m.organization_id = v_org_id
      and (m.sender_id = auth.uid() or m.recipient_id = auth.uid())
  ),
  ranked as (
    select
      s.*,
      row_number() over (partition by s.thread_key order by s.created_at desc) as rn
    from scoped s
  ),
  unread as (
    select
      s.thread_key,
      count(*)::integer as unread_count
    from scoped s
    where s.recipient_id = auth.uid()
      and s.read_at is null
    group by s.thread_key
  )
  select
    r.thread_key,
    r.cp_id as counterparty_id,
    coalesce(p.full_name, p.email, 'Unknown') as counterparty_name,
    r.message as last_message,
    r.subject as last_subject,
    r.created_at as last_created_at,
    coalesce(u.unread_count, 0) as unread_count
  from ranked r
  left join public.profiles p on p.id = r.cp_id
  left join unread u on u.thread_key = r.thread_key
  where r.rn = 1
  order by r.created_at desc
  limit greatest(coalesce(p_limit, 100), 1);
end;
$$;


-- Name: mark_my_notification_read(uuid); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.mark_my_notification_read(p_notification_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
begin
  v_org_id := public.current_organization_id(auth.uid());
  if v_org_id is null then
    raise exception 'Organization context is required.';
  end if;

  update public.app_notifications
  set read_at = coalesce(read_at, now())
  where id = p_notification_id
    and organization_id = v_org_id
    and recipient_id = auth.uid();

  return found;
end;
$$;


-- Name: notify_employee_message_insert(); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.notify_employee_message_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_subject text;
begin
  v_subject := nullif(trim(coalesce(new.subject, '')), '');
  insert into public.app_notifications (
    organization_id,
    recipient_id,
    actor_id,
    category,
    title,
    body,
    payload
  )
  values (
    new.organization_id,
    new.recipient_id,
    new.sender_id,
    'message_received',
    'New Message',
    coalesce(v_subject, left(new.message, 120)),
    jsonb_build_object('message_id', new.id)
  );

  return new;
end;
$$;


-- Name: notify_task_assignment_insert(); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.notify_task_assignment_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_task_title text;
begin
  select title into v_task_title from public.tasks where id = new.task_id;

  insert into public.app_notifications (
    organization_id,
    recipient_id,
    actor_id,
    category,
    title,
    body,
    payload
  )
  values (
    new.organization_id,
    new.employee_id,
    new.assigned_by,
    'task_assigned',
    'New Task Assigned',
    coalesce(v_task_title, 'You have a new task assignment.'),
    jsonb_build_object('task_assignment_id', new.id, 'task_id', new.task_id)
  );

  return new;
end;
$$;


-- Name: notify_training_assignment_insert(); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.notify_training_assignment_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_course_title text;
begin
  select title into v_course_title from public.training_courses where id = new.course_id;

  insert into public.app_notifications (
    organization_id,
    recipient_id,
    actor_id,
    category,
    title,
    body,
    payload
  )
  values (
    new.organization_id,
    new.employee_id,
    new.assigned_by,
    'training_assigned',
    'New Training Assigned',
    coalesce(v_course_title, 'A training has been assigned to you.'),
    jsonb_build_object('training_assignment_id', new.id, 'course_id', new.course_id)
  );

  return new;
end;
$$;


-- Name: preview_time_off_coverage_impact(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.preview_time_off_coverage_impact(p_employee_id uuid, p_start_date date, p_end_date date) RETURNS TABLE(day_date date, employee_shift_count integer, employee_task_count integer, work_areas_impacted text[], unassigned_pool_openings integer, risk_level text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
begin
  v_org_id := public.current_organization_id(auth.uid());
  if v_org_id is null then
    raise exception 'Organization context is required.';
  end if;

  if p_start_date is null or p_end_date is null or p_end_date < p_start_date then
    raise exception 'Invalid date range.';
  end if;

  if auth.uid() <> p_employee_id and not exists (
    select 1 from public.profiles p
    where p.id = auth.uid()
      and p.organization_id = v_org_id
      and p.role = 'admin'::public.app_role
  ) then
    raise exception 'Only self or admin can preview PTO impact.';
  end if;

  return query
  with day_series as (
    select generate_series(p_start_date, p_end_date, interval '1 day')::date as d
  ), impacts as (
    select
      ds.d as day_date,
      (
        select count(*)
        from public.shifts s
        where s.organization_id = v_org_id
          and s.employee_id = p_employee_id
          and s.start_at::date = ds.d
      )::integer as employee_shift_count,
      (
        select count(*)
        from public.tasks t
        join public.task_assignments ta on ta.task_id = t.id
        where ta.organization_id = v_org_id
          and ta.employee_id = p_employee_id
          and t.start_at::date = ds.d
      )::integer as employee_task_count,
      (
        select coalesce(array_agg(distinct wa.name order by wa.name), array[]::text[])
        from public.shifts s
        left join public.work_areas wa on wa.id = s.work_area_id
        where s.organization_id = v_org_id
          and s.employee_id = p_employee_id
          and s.start_at::date = ds.d
      ) as work_areas_impacted,
      (
        select count(*)
        from public.shifts s
        where s.organization_id = v_org_id
          and s.is_shift_pool = true
          and s.employee_id is null
          and s.start_at::date = ds.d
      )::integer as unassigned_pool_openings
    from day_series ds
  )
  select
    i.day_date,
    i.employee_shift_count,
    i.employee_task_count,
    i.work_areas_impacted,
    i.unassigned_pool_openings,
    case
      when i.employee_shift_count + i.employee_task_count = 0 then 'low'
      when i.unassigned_pool_openings > 0 then 'medium'
      else 'high'
    end as risk_level
  from impacts i
  order by i.day_date;
end;
$$;


-- Name: process_due_shift_auto_clock_outs(); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.process_due_shift_auto_clock_outs() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_is_admin boolean := false;
  v_count integer := 0;
begin
  v_org_id := public.current_organization_id(auth.uid());
  if v_org_id is null then
    raise exception 'Organization context is required.';
  end if;

  select exists (
    select 1
    from public.profiles p
    where p.id = auth.uid()
      and p.organization_id = v_org_id
      and p.role = 'admin'::public.app_role
  )
  into v_is_admin;

  with due as (
    select
      s.id,
      s.end_at + interval '30 minutes' as auto_clock_out_at
    from public.shifts s
    where s.organization_id = v_org_id
      and s.clocked_in_at is not null
      and s.clocked_out_at is null
      and s.status <> 'off_shift'
      and s.end_at + interval '30 minutes' <= now()
      and (v_is_admin or s.employee_id = auth.uid())
  )
  update public.shifts s
  set status = 'off_shift',
      clocked_out_at = due.auto_clock_out_at,
      updated_by = auth.uid(),
      updated_at = now()
  from due
  where s.id = due.id;

  get diagnostics v_count = row_count;
  return coalesce(v_count, 0);
end;
$$;


-- Name: process_due_shift_break_resumes(); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.process_due_shift_break_resumes() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_count integer := 0;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required.';
  end if;

  v_org_id := public.current_organization_id(auth.uid());
  if v_org_id is null then
    return 0;
  end if;

  with due as (
    select sbs.id, sbs.shift_id, sbs.break_task_id
    from public.shift_break_schedules sbs
    join public.shifts s on s.id = sbs.shift_id
    where sbs.organization_id = v_org_id
      and sbs.resumed_at is null
      and sbs.break_ends_at <= now()
      and s.status = 'break'
      and s.employee_id = sbs.employee_id
    for update of sbs, s
  ),
  updated_shifts as (
    update public.shifts s
    set status = 'on_duty',
        clocked_out_at = null,
        updated_by = auth.uid()
    from due d
    where s.id = d.shift_id
    returning d.id, d.break_task_id
  ),
  completed_tasks as (
    update public.tasks t
    set status = 'done',
        updated_by = auth.uid(),
        updated_at = now()
    from updated_shifts us
    where t.id = us.break_task_id
    returning us.id
  )
  update public.shift_break_schedules sbs
  set resumed_at = now(),
      updated_by = auth.uid()
  from updated_shifts us
  where sbs.id = us.id;

  get diagnostics v_count = row_count;
  return coalesce(v_count, 0);
end;
$$;


-- Name: process_retail_floor_chaos(); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.process_retail_floor_chaos() RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.process_retail_floor_chaos(null::uuid, now());
$$;


-- Name: process_retail_floor_chaos(uuid); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.process_retail_floor_chaos(p_organization_id uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.process_retail_floor_chaos(p_organization_id, now());
$$;


-- Name: process_retail_floor_chaos(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.process_retail_floor_chaos(p_organization_id uuid DEFAULT NULL::uuid, p_now timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_org_id uuid;
  v_enabled boolean := false;
  v_lock_key bigint;
  v_clocked_in integer := 0;
  v_moved integer := 0;
  v_breaks_started integer := 0;
  v_breaks_resumed integer := 0;
  v_clocked_out integer := 0;
  v_messages_created integer := 0;
  v_tasks_created integer := 0;
  v_trainings_assigned integer := 0;
  v_task_id uuid;
  v_shift_id uuid;
  v_shift_start timestamptz;
  v_shift_end timestamptz;
  v_task_start timestamptz;
  v_task_end timestamptz;
  v_course_id uuid;
  v_employee_id uuid;
  v_duration_minutes integer;
  v_due_at timestamptz;
  v_row record;
begin
  if v_actor_id is null then
    raise exception 'Authentication is required.';
  end if;

  v_org_id := coalesce(p_organization_id, public.current_organization_id(v_actor_id));
  if v_org_id is null then
    raise exception 'Organization context is required.';
  end if;

  if not public.is_same_org(v_org_id, v_actor_id) then
    raise exception 'Cross-organization execution is not allowed.';
  end if;

  select o.enable_retail_floor_simulation
    into v_enabled
  from public.organizations o
  where o.id = v_org_id;

  if not coalesce(v_enabled, false) then
    return jsonb_build_object(
      'organization_id', v_org_id,
      'enabled', false
    );
  end if;

  v_lock_key := hashtext('retail_floor_chaos:' || v_org_id::text)::bigint;
  if not pg_try_advisory_xact_lock(v_lock_key) then
    return jsonb_build_object(
      'organization_id', v_org_id,
      'enabled', true,
      'skipped', 'busy'
    );
  end if;

  update public.shifts s
  set status = 'on_duty',
      clocked_in_at = coalesce(s.clocked_in_at, p_now),
      clocked_out_at = null,
      updated_by = coalesce(v_actor_id, s.updated_by),
      updated_at = p_now
  where s.organization_id = v_org_id
    and s.employee_id is not null
    and s.status = 'scheduled'
    and s.start_at <= p_now
    and s.end_at >= p_now
    and s.clocked_in_at is null
    and random() < 0.96;
  get diagnostics v_clocked_in = row_count;

  with moved as (
    update public.shifts s
    set work_area_id = (
          select w.id
          from public.work_areas w
          where w.organization_id = v_org_id
            and w.is_active = true
            and lower(trim(coalesce(w.name, ''))) not in ('management', 'operator')
            and w.id is distinct from s.work_area_id
          order by random()
          limit 1
        ),
        notes = trim(concat(coalesce(s.notes, ''), ' [Retail chaos: moved areas because manager drama]')),
        updated_by = coalesce(v_actor_id, s.updated_by),
        updated_at = p_now
    where s.organization_id = v_org_id
      and s.employee_id is not null
      and s.status = 'on_duty'
      and s.start_at <= p_now
      and s.end_at >= p_now
      and random() < 0.38
      and not exists (
        select 1
        from public.profiles p
        where p.id = s.employee_id
          and p.organization_id = v_org_id
          and coalesce(p.retail_chaos_stationary, false) = true
      )
      and coalesce((
        select lower(trim(coalesce(wa0.name, '')))
        from public.work_areas wa0
        where wa0.id = s.work_area_id
          and wa0.organization_id = s.organization_id
      ), '') not in ('management', 'operator')
      and exists (
        select 1
        from public.work_areas w
        where w.organization_id = v_org_id
          and w.is_active = true
          and lower(trim(coalesce(w.name, ''))) not in ('management', 'operator')
          and w.id is distinct from s.work_area_id
      )
    returning 1
  )
  select count(*)::integer into v_moved from moved;

  update public.shifts s
  set status = 'break',
      clocked_out_at = coalesce(s.clocked_out_at, p_now),
      notes = trim(concat(coalesce(s.notes, ''), ' [Retail chaos: random break protest]')),
      updated_by = coalesce(v_actor_id, s.updated_by),
      updated_at = p_now
  where s.organization_id = v_org_id
    and s.employee_id is not null
    and s.status = 'on_duty'
    and s.start_at <= p_now - interval '15 minutes'
    and s.end_at >= p_now + interval '10 minutes'
    and random() < 0.33;
  get diagnostics v_breaks_started = row_count;

  update public.shifts s
  set status = 'on_duty',
      clocked_out_at = null,
      updated_by = coalesce(v_actor_id, s.updated_by),
      updated_at = p_now
  where s.organization_id = v_org_id
    and s.employee_id is not null
    and s.status = 'break'
    and (
      (s.clocked_out_at is not null and p_now - s.clocked_out_at >= interval '3 minutes')
      or random() < 0.47
    );
  get diagnostics v_breaks_resumed = row_count;

  update public.shifts s
  set status = 'off_shift',
      clocked_out_at = coalesce(s.clocked_out_at, p_now),
      worked_minutes = coalesce(
        s.worked_minutes,
        greatest(
          0,
          floor(extract(epoch from (coalesce(s.clocked_out_at, p_now) - coalesce(s.clocked_in_at, s.start_at))) / 60.0)::integer
            - greatest(coalesce(s.break_minutes, 0), 0)
        )
      ),
      updated_by = coalesce(v_actor_id, s.updated_by),
      updated_at = p_now
  where s.organization_id = v_org_id
    and s.employee_id is not null
    and s.status <> 'off_shift'
    and s.end_at < p_now;
  get diagnostics v_clocked_out = row_count;

  insert into public.employee_messages (
    id,
    organization_id,
    sender_id,
    recipient_id,
    subject,
    message,
    read_at,
    created_at
  )
  select
    gen_random_uuid(),
    v_org_id,
    sender.employee_id,
    recipient.id,
    msg.subject,
    msg.body,
    null,
    p_now
  from (
    select distinct s.employee_id
    from public.shifts s
    where s.organization_id = v_org_id
      and s.employee_id is not null
      and s.start_at <= p_now
      and s.end_at >= p_now
      and s.status in ('scheduled', 'on_duty', 'break')
      and random() < 0.42
    limit 20
  ) sender
  join lateral (
    select p.id
    from public.profiles p
    where p.organization_id = v_org_id
      and p.id <> sender.employee_id
      and (
        p.role = 'admin'::public.app_role
        or coalesce(p.is_training_manager, false) = true
        or public.has_operator_shift_access(p.id)
        or public.has_management_shift_access(p.id)
      )
    order by random()
    limit 1
  ) recipient on true
  join lateral (
    select
      (array[
        'Work Area Rant',
        'Break Meltdown',
        'Shift Opinion',
        'Retail Energy',
        'Fit Alert',
        'Pay Raise Plea',
        'Boss Complaint'
      ])[1 + floor(random() * 7)::integer] as subject,
      (array[
        'Why am I in this area again? This zone is chaos today.',
        'I am taking a break right now. This is not a request.',
        'Today feels overloaded. We need coverage moved ASAP.',
        'Customer-style rush hit us hard. We need backup immediately.',
        'I am throwing a fit about this assignment and everyone knows it.',
        'Please raise my pay. I am doing three peoples jobs right now.',
        'My boss keeps moving me everywhere. I need help or a raise.'
      ])[1 + floor(random() * 7)::integer] as body
  ) msg on true;
  get diagnostics v_messages_created = row_count;

  for v_row in
    select
      wa.id as work_area_id,
      wa.name as work_area_name,
      coalesce(
        (
          select s.employee_id
          from public.shifts s
          where s.organization_id = v_org_id
            and s.work_area_id = wa.id
            and s.employee_id is not null
            and s.status = 'on_duty'
            and s.start_at <= p_now
            and s.end_at >= p_now
          order by random()
          limit 1
        ),
        (
          select s2.employee_id
          from public.shifts s2
          where s2.organization_id = v_org_id
            and s2.employee_id is not null
            and s2.status in ('scheduled', 'on_duty', 'break')
            and s2.start_at <= p_now
            and s2.end_at >= p_now
          order by random()
          limit 1
        )
      ) as employee_id
    from public.work_areas wa
    where wa.organization_id = v_org_id
      and wa.is_active = true
      and random() < 0.58
      and not exists (
        select 1
        from public.tasks t
        where t.organization_id = v_org_id
          and t.work_area_id = wa.id
          and t.source_system = 'retail_chaos'
          and t.created_at >= p_now - interval '20 minutes'
      )
  loop
    if v_row.employee_id is null then
      continue;
    end if;

    select s.id, s.start_at, s.end_at
      into v_shift_id, v_shift_start, v_shift_end
    from public.shifts s
    where s.organization_id = v_org_id
      and s.employee_id = v_row.employee_id
      and s.status <> 'off_shift'
      and s.start_at <= p_now
      and s.end_at >= p_now
    order by s.start_at asc
    limit 1;

    if v_shift_id is null then
      continue;
    end if;

    v_duration_minutes := 20 + floor(random() * 140)::integer;
    v_task_start := greatest(p_now, v_shift_start);
    v_task_end := least(v_shift_end, p_now + make_interval(mins => v_duration_minutes));
    if v_task_end <= v_task_start then
      continue;
    end if;

    insert into public.tasks (
      id,
      organization_id,
      title,
      description,
      status,
      priority,
      source_system,
      start_at,
      end_at,
      work_area_id,
      shift_id,
      created_by,
      updated_by,
      created_at,
      updated_at
    )
    values (
      gen_random_uuid(),
      v_org_id,
      (array[
        'Rush Coverage - ',
        'Recovery Sweep - ',
        'Stock Rework - ',
        'Frontline Rescue - ',
        'Customer Queue Drain - '
      ])[1 + floor(random() * 5)::integer] || v_row.work_area_name,
      'Auto-generated by retail chaos mode for real-time floor pressure.',
      'pending',
      'high',
      'retail_chaos',
      v_task_start,
      v_task_end,
      v_row.work_area_id,
      v_shift_id,
      coalesce(v_actor_id, v_row.employee_id),
      coalesce(v_actor_id, v_row.employee_id),
      p_now,
      p_now
    )
    returning id into v_task_id;

    insert into public.task_assignments (
      id,
      organization_id,
      task_id,
      employee_id,
      assigned_by,
      assigned_at
    )
    values (
      gen_random_uuid(),
      v_org_id,
      v_task_id,
      v_row.employee_id,
      coalesce(v_actor_id, v_row.employee_id),
      p_now
    )
    on conflict do nothing;

    v_tasks_created := v_tasks_created + 1;
  end loop;

  for v_row in select generate_series(1, 3) as n loop
    if random() >= 0.65 then
      continue;
    end if;

    select tc.id
      into v_course_id
    from public.training_courses tc
    where tc.organization_id = v_org_id
      and tc.is_active = true
    order by random()
    limit 1;

    if v_course_id is null then
      continue;
    end if;

    select p.id
      into v_employee_id
    from public.profiles p
    where p.organization_id = v_org_id
      and p.role = 'employee'::public.app_role
    order by random()
    limit 1;

    if v_employee_id is null then
      continue;
    end if;

    v_due_at := p_now + make_interval(mins => 12 + floor(random() * 60)::integer);

    insert into public.training_assignments (
      id,
      organization_id,
      course_id,
      employee_id,
      assigned_by,
      assigned_at,
      due_at,
      status,
      completion_notes,
      updated_at
    )
    values (
      gen_random_uuid(),
      v_org_id,
      v_course_id,
      v_employee_id,
      coalesce(v_actor_id, v_employee_id),
      p_now,
      v_due_at,
      'assigned',
      'Auto-assigned by retail chaos mode.',
      p_now
    )
    on conflict (course_id, employee_id)
    do update set
      assigned_by = excluded.assigned_by,
      assigned_at = excluded.assigned_at,
      due_at = excluded.due_at,
      status = case when public.training_assignments.status = 'completed' then 'completed' else 'assigned' end,
      completed_at = case when public.training_assignments.status = 'completed' then public.training_assignments.completed_at else null end,
      completion_notes = case when public.training_assignments.status = 'completed' then public.training_assignments.completion_notes else excluded.completion_notes end,
      updated_at = excluded.updated_at;

    v_trainings_assigned := v_trainings_assigned + 1;
  end loop;

  return jsonb_build_object(
    'organization_id', v_org_id,
    'enabled', true,
    'clocked_in', v_clocked_in,
    'moved', v_moved,
    'breaks_started', v_breaks_started,
    'breaks_resumed', v_breaks_resumed,
    'clocked_out', v_clocked_out,
    'messages_created', v_messages_created,
    'tasks_created', v_tasks_created,
    'trainings_assigned', v_trainings_assigned
  );
end;
$$;


-- Name: protect_employee_message_update(); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.protect_employee_message_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.sender_id is distinct from old.sender_id
    or new.recipient_id is distinct from old.recipient_id
    or new.subject is distinct from old.subject
    or new.message is distinct from old.message
    or new.organization_id is distinct from old.organization_id
    or new.created_at is distinct from old.created_at then
    raise exception 'Only read state can be updated for messages.';
  end if;

  return new;
end;
$$;


-- Name: protect_profile_admin_fields(); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.protect_profile_admin_fields() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_has_admin boolean;
begin
  if auth.uid() is not null and not public.is_admin(auth.uid()) then
    if new.role is distinct from old.role then
      if old.role = 'employee'
        and new.role = 'admin'
        and old.organization_id is not null then
        select exists (
          select 1
          from public.profiles p
          where p.organization_id = old.organization_id
            and p.role = 'admin'
            and p.id <> old.id
        )
        into v_org_has_admin;

        if not v_org_has_admin then
          return new;
        end if;
      end if;

      raise exception 'Only admins can update role.';
    end if;

    if new.hourly_rate is distinct from old.hourly_rate then
      raise exception 'Only admins can update hourly rate.';
    end if;
  end if;

  return new;
end;
$$;


-- Name: employee_device_tokens; Type: TABLE; Schema: public; Owner: -

CREATE TABLE public.employee_device_tokens (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    employee_id uuid NOT NULL,
    platform text DEFAULT 'ios'::text NOT NULL,
    device_token text NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    last_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT employee_device_tokens_platform_check CHECK ((platform = 'ios'::text))
);


-- Name: register_my_device_token(text, text); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.register_my_device_token(p_device_token text, p_platform text DEFAULT 'ios'::text) RETURNS public.employee_device_tokens
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_token text;
  v_platform text;
  v_row public.employee_device_tokens%rowtype;
begin
  v_org_id := public.current_organization_id(auth.uid());
  if v_org_id is null then
    raise exception 'Organization context is required.';
  end if;

  v_token := trim(coalesce(p_device_token, ''));
  if v_token = '' then
    raise exception 'Device token is required.';
  end if;

  v_platform := lower(trim(coalesce(p_platform, 'ios')));
  if v_platform <> 'ios' then
    raise exception 'Unsupported platform.';
  end if;

  insert into public.employee_device_tokens (
    organization_id,
    employee_id,
    platform,
    device_token,
    is_active,
    last_seen_at
  )
  values (
    v_org_id,
    auth.uid(),
    v_platform,
    v_token,
    true,
    now()
  )
  on conflict (employee_id, platform, device_token)
  do update
  set is_active = true,
      last_seen_at = now(),
      updated_at = now()
  returning * into v_row;

  return v_row;
end;
$$;


-- Name: review_overtime_request(uuid, public.overtime_request_status, text); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.review_overtime_request(p_request_id uuid, p_status public.overtime_request_status, p_review_notes text DEFAULT ''::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_employee_id uuid;
  v_org_id uuid;
  v_start timestamptz;
  v_end timestamptz;
  v_existing_status public.overtime_request_status;
  v_overtime_type public.overtime_request_type;
  v_assigned_by uuid;
  v_shift_id uuid;
  v_next_shift public.shifts%rowtype;
  v_prev_shift public.shifts%rowtype;
  v_work_area_id uuid;
  v_gap_next_seconds double precision;
  v_gap_prev_seconds double precision;
  v_actor_is_admin boolean := false;
begin
  v_actor_is_admin := public.is_admin(auth.uid());

  select employee_id, organization_id, start_at, end_at, status, overtime_type, assigned_by
    into v_employee_id, v_org_id, v_start, v_end, v_existing_status, v_overtime_type, v_assigned_by
  from public.overtime_requests
  where id = p_request_id;

  if v_employee_id is null then
    raise exception 'Overtime request not found.';
  end if;

  if v_org_id is not null and not public.is_same_org(v_org_id, auth.uid()) then
    raise exception 'Cross-organization review is not allowed.';
  end if;

  if v_org_id is null then
    v_org_id := public.current_organization_id(v_employee_id);
  end if;

  if v_org_id is null then
    raise exception 'Overtime request is missing organization context.';
  end if;

  if not v_actor_is_admin then
    if v_employee_id <> auth.uid() then
      raise exception 'Only admins or assigned employees can respond to overtime requests.';
    end if;

    if coalesce(v_overtime_type, 'voluntary'::public.overtime_request_type) <> 'voluntary'::public.overtime_request_type then
      raise exception 'Only voluntary overtime requests can be employee-responded.';
    end if;

    if v_assigned_by is null then
      raise exception 'Only admin-assigned overtime requests can be employee-responded.';
    end if;

    if p_status not in ('approved'::public.overtime_request_status, 'denied'::public.overtime_request_status) then
      raise exception 'Employee response must be approved or denied.';
    end if;
  end if;

  if v_existing_status <> 'pending' then
    raise exception 'Only pending overtime requests can be reviewed.';
  end if;

  update public.overtime_requests
  set status = p_status,
      reviewed_by = auth.uid(),
      reviewed_at = now(),
      review_notes = coalesce(p_review_notes, '')
  where id = p_request_id;

  if p_status <> 'approved' then
    return null;
  end if;

  -- Prevent overlapping shifts (no double-booking).
  if exists (
    select 1
    from public.shifts s
    where s.employee_id = v_employee_id
      and public.is_same_org(s.organization_id, auth.uid())
      and tstzrange(s.start_at, s.end_at, '[)') && tstzrange(v_start, v_end, '[)')
  ) then
    raise exception 'Approved overtime window overlaps an existing shift.';
  end if;

  select *
    into v_next_shift
  from public.shifts s
  where s.employee_id = v_employee_id
    and public.is_same_org(s.organization_id, auth.uid())
    and s.start_at >= v_end
  order by s.start_at asc
  limit 1;

  select *
    into v_prev_shift
  from public.shifts s
  where s.employee_id = v_employee_id
    and public.is_same_org(s.organization_id, auth.uid())
    and s.end_at <= v_start
  order by s.end_at desc
  limit 1;

  if v_next_shift.id is not null then
    v_gap_next_seconds := extract(epoch from (v_next_shift.start_at - v_end));
  end if;

  if v_prev_shift.id is not null then
    v_gap_prev_seconds := extract(epoch from (v_start - v_prev_shift.end_at));
  end if;

  if v_next_shift.id is not null and v_prev_shift.id is not null then
    if coalesce(v_gap_prev_seconds, 1e18) <= coalesce(v_gap_next_seconds, 1e18) then
      v_work_area_id := v_prev_shift.work_area_id;
    else
      v_work_area_id := v_next_shift.work_area_id;
    end if;
  elsif v_next_shift.id is not null then
    v_work_area_id := v_next_shift.work_area_id;
  elsif v_prev_shift.id is not null then
    v_work_area_id := v_prev_shift.work_area_id;
  else
    v_work_area_id := null;
  end if;

  insert into public.shifts (
    employee_id,
    work_area_id,
    start_at,
    end_at,
    status,
    break_minutes,
    notes,
    pay_multiplier,
    is_unscheduled_overtime,
    created_by,
    updated_by,
    organization_id
  )
  values (
    v_employee_id,
    v_work_area_id,
    v_start,
    v_end,
    'scheduled',
    0,
    case
      when v_actor_is_admin then 'Approved overtime request'
      else 'Accepted assigned overtime request'
    end,
    1.5,
    false,
    auth.uid(),
    auth.uid(),
    v_org_id
  )
  returning id into v_shift_id;

  update public.overtime_requests
  set approved_shift_id = v_shift_id
  where id = p_request_id;

  return v_shift_id;
end;
$$;


-- Name: review_shift_swap_request(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.review_shift_swap_request(p_request_id uuid, p_approve boolean, p_review_note text DEFAULT ''::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_req public.shift_swap_requests%rowtype;
  v_target_employee uuid;
begin
  v_org_id := public.current_organization_id(auth.uid());
  if v_org_id is null then
    raise exception 'Organization context is required.';
  end if;

  if not exists (
    select 1
    from public.profiles p
    where p.id = auth.uid()
      and p.organization_id = v_org_id
      and p.role = 'admin'::public.app_role
  ) then
    raise exception 'Only admins can review shift swap requests.';
  end if;

  select *
    into v_req
  from public.shift_swap_requests r
  where r.id = p_request_id
    and r.organization_id = v_org_id;

  if v_req.id is null then
    raise exception 'Swap request not found.';
  end if;

  if v_req.status not in ('open', 'pending_admin') then
    raise exception 'Swap request is already finalized.';
  end if;

  v_target_employee := coalesce(v_req.accepted_by_employee_id, v_req.requested_employee_id);
  if p_approve and v_target_employee is null then
    raise exception 'No target employee has accepted this swap yet.';
  end if;

  if p_approve then
    update public.shifts
    set employee_id = v_target_employee,
        updated_by = auth.uid(),
        updated_at = now()
    where id = v_req.shift_id
      and organization_id = v_org_id;
  end if;

  update public.shift_swap_requests
  set status = case when p_approve then 'approved' else 'denied' end,
      review_note = trim(coalesce(p_review_note, '')),
      reviewed_by = auth.uid(),
      reviewed_at = now(),
      updated_at = now()
  where id = p_request_id;

  return p_request_id;
end;
$$;


-- Name: revoke_discipline_action(uuid, text); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.revoke_discipline_action(p_action_id uuid, p_review_notes text DEFAULT ''::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_action public.discipline_actions%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required.';
  end if;

  if not public.is_admin(auth.uid()) then
    raise exception 'Only admins can revoke discipline actions.';
  end if;

  select *
    into v_action
  from public.discipline_actions da
  where da.id = p_action_id
  for update;

  if v_action.id is null then
    raise exception 'Discipline action not found.';
  end if;

  if not public.is_same_org(v_action.organization_id, auth.uid()) then
    raise exception 'Cannot revoke discipline across organizations.';
  end if;

  if v_action.status = 'revoked' then
    return true;
  end if;

  update public.discipline_actions
  set status = 'revoked',
      reviewed_by = auth.uid(),
      reviewed_at = now(),
      review_notes = coalesce(p_review_notes, ''),
      updated_by = auth.uid()
  where id = p_action_id;

  return true;
end;
$$;


-- Name: send_employee_message(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.send_employee_message(p_recipient_id uuid, p_subject text DEFAULT ''::text, p_message text DEFAULT ''::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_message_id uuid;
  v_body text;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required.';
  end if;

  v_org_id := public.current_organization_id(auth.uid());
  if v_org_id is null then
    raise exception 'Organization context is required.';
  end if;

  v_body := trim(coalesce(p_message, ''));
  if v_body = '' then
    raise exception 'Message is required.';
  end if;

  if not exists (
    select 1
    from public.profiles recipient
    where recipient.id = p_recipient_id
      and recipient.organization_id = v_org_id
      and recipient.id <> auth.uid()
  ) then
    raise exception 'Recipient must be in your organization.';
  end if;

  insert into public.employee_messages (
    organization_id,
    sender_id,
    recipient_id,
    subject,
    message,
    read_at,
    created_at
  )
  values (
    v_org_id,
    auth.uid(),
    p_recipient_id,
    trim(coalesce(p_subject, '')),
    v_body,
    null,
    now()
  )
  returning id into v_message_id;

  return v_message_id;
end;
$$;


-- Name: send_employee_message_to_leadership(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.send_employee_message_to_leadership(p_recipient_id uuid, p_subject text DEFAULT ''::text, p_message text DEFAULT ''::text) RETURNS uuid
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.send_employee_message(p_recipient_id, p_subject, p_message)
$$;


-- Name: server_now(); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.server_now() RETURNS timestamp with time zone
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select now();
$$;


-- Name: set_employee_message_thread_key(); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.set_employee_message_thread_key() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  new.thread_key := public.employee_message_thread_key(new.sender_id, new.recipient_id);
  return new;
end;
$$;


-- Name: set_employee_retail_chaos_stationary(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.set_employee_retail_chaos_stationary(p_employee_id uuid, p_stationary boolean DEFAULT true) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required.';
  end if;

  v_org_id := public.current_organization_id(auth.uid());
  if v_org_id is null then
    raise exception 'Organization context is required.';
  end if;

  if not public.is_admin(auth.uid()) then
    raise exception 'Only admins can update chaos movement lock.';
  end if;

  update public.profiles p
  set retail_chaos_stationary = coalesce(p_stationary, true),
      updated_at = now()
  where p.id = p_employee_id
    and p.organization_id = v_org_id
    and p.role = 'employee'::public.app_role;

  return found;
end;
$$;


-- Name: set_shift_pool_status(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.set_shift_pool_status(p_shift_id uuid, p_enable boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_status public.shift_status;
  v_clocked_in_at timestamptz;
  v_end_at timestamptz;
begin
  if not public.is_admin(auth.uid()) then
    raise exception 'Only admins can manage shift pool status.';
  end if;

  select organization_id, status, clocked_in_at, end_at
    into v_org_id, v_status, v_clocked_in_at, v_end_at
  from public.shifts
  where id = p_shift_id
  for update;

  if v_org_id is null then
    raise exception 'Shift not found.';
  end if;

  if not public.is_same_org(v_org_id, auth.uid()) then
    raise exception 'Cannot manage shift pool across organizations.';
  end if;

  if p_enable then
    if v_status <> 'scheduled' then
      raise exception 'Only scheduled shifts can be posted to the shift pool.';
    end if;

    if v_clocked_in_at is not null then
      raise exception 'Clocked-in shifts cannot be posted to the shift pool.';
    end if;

    if v_end_at <= now() then
      raise exception 'Past shifts cannot be posted to the shift pool.';
    end if;

    if exists (
      select 1
      from public.tasks t
      where t.shift_id = p_shift_id
    ) then
      raise exception 'Shift with linked tasks cannot be posted to the shift pool.';
    end if;
  end if;

  update public.shifts
  set is_shift_pool = p_enable,
      shift_pool_posted_at = case when p_enable then now() else null end,
      shift_pool_posted_by = case when p_enable then auth.uid() else null end,
      employee_id = case when p_enable then null else employee_id end,
      shift_pool_claimed_at = case when p_enable then null else shift_pool_claimed_at end,
      shift_pool_claimed_by = case when p_enable then null else shift_pool_claimed_by end,
      updated_by = auth.uid()
  where id = p_shift_id;

  return true;
end;
$$;


-- Name: set_shift_worked_minutes(); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.set_shift_worked_minutes() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.clocked_in_at is not null and new.clocked_out_at is not null then
    new.worked_minutes := public.calculate_shift_paid_minutes(
      new.clocked_in_at,
      new.clocked_out_at,
      new.start_at,
      new.break_minutes,
      5
    );
  elsif new.status = 'off_shift' then
    new.worked_minutes := public.calculate_shift_worked_minutes(new.start_at, new.end_at, new.break_minutes);
  else
    new.worked_minutes := null;
  end if;

  return new;
end;
$$;


-- Name: touch_updated_at(); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;


-- Name: unregister_my_device_token(text, text); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.unregister_my_device_token(p_device_token text, p_platform text DEFAULT 'ios'::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_token text;
  v_platform text;
begin
  v_org_id := public.current_organization_id(auth.uid());
  if v_org_id is null then
    raise exception 'Organization context is required.';
  end if;

  v_token := trim(coalesce(p_device_token, ''));
  if v_token = '' then
    return false;
  end if;

  v_platform := lower(trim(coalesce(p_platform, 'ios')));

  update public.employee_device_tokens
  set is_active = false,
      updated_at = now()
  where organization_id = v_org_id
    and employee_id = auth.uid()
    and platform = v_platform
    and device_token = v_token;

  return found;
end;
$$;


-- Name: update_shift_work_area(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.update_shift_work_area(p_shift_id uuid, p_work_area_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_work_area_org_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required.';
  end if;

  if not public.is_admin(auth.uid()) then
    raise exception 'Only admins can update shift work areas.';
  end if;

  select s.organization_id
    into v_org_id
  from public.shifts s
  where s.id = p_shift_id
  for update;

  if v_org_id is null then
    raise exception 'Shift not found.';
  end if;

  if not public.is_same_org(v_org_id, auth.uid()) then
    raise exception 'Cannot update shifts across organizations.';
  end if;

  if p_work_area_id is not null then
    select wa.organization_id
      into v_work_area_org_id
    from public.work_areas wa
    where wa.id = p_work_area_id
      and wa.is_active = true;

    if v_work_area_org_id is null or v_work_area_org_id <> v_org_id then
      raise exception 'Work area is not active in your organization.';
    end if;
  end if;

  update public.shifts
  set work_area_id = p_work_area_id,
      updated_by = auth.uid()
  where id = p_shift_id;

  return found;
end;
$$;


-- Name: organizations; Type: TABLE; Schema: public; Owner: -

CREATE TABLE public.organizations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    admin_portal_label text DEFAULT 'WROC ADMIN'::text NOT NULL,
    enable_extended_leave_lock boolean DEFAULT true NOT NULL,
    extended_leave_threshold_days integer DEFAULT 5 NOT NULL,
    enable_admin_realtime_notifications boolean DEFAULT true NOT NULL,
    default_timeline_window_hours integer DEFAULT 8 NOT NULL,
    default_shift_break_minutes integer DEFAULT 30 NOT NULL,
    enable_onboarding boolean DEFAULT true NOT NULL,
    onboarding_version integer DEFAULT 1 NOT NULL,
    onboarding_title text DEFAULT 'Welcome to your organization'::text NOT NULL,
    onboarding_description text DEFAULT ''::text NOT NULL,
    onboarding_required_acknowledgements text[] DEFAULT ARRAY['I understand attendance and punctuality expectations.'::text, 'I understand safety and reporting expectations.'::text, 'I understand communication and conduct expectations.'::text] NOT NULL,
    onboarding_custom_questions jsonb DEFAULT '[]'::jsonb NOT NULL,
    onboarding_email_subject text DEFAULT 'Welcome to {{organization_name}}, {{employee_name}}'::text NOT NULL,
    onboarding_email_body text DEFAULT 'Hi {{employee_name}},

Your WaterSuite account is ready.

Login URL: {{login_url}}
Organization Code: {{organization_code}}
Temporary Password: {{temporary_password}}

Please complete onboarding after your first login and then change your password.

- {{organization_name}}'::text NOT NULL,
    training_time_multiplier integer DEFAULT 10 NOT NULL,
    training_fake_employee_count integer DEFAULT 18 NOT NULL,
    training_no_show_rate_percent integer DEFAULT 12 NOT NULL,
    training_task_ack_rate_percent integer DEFAULT 82 NOT NULL,
    training_clock_in_early_min integer DEFAULT '-7'::integer NOT NULL,
    training_clock_in_late_min integer DEFAULT 9 NOT NULL,
    training_clock_out_early_min integer DEFAULT '-4'::integer NOT NULL,
    training_clock_out_late_min integer DEFAULT 14 NOT NULL,
    login_primary_color text DEFAULT '#103b84'::text NOT NULL,
    login_accent_color text DEFAULT '#1850b7'::text NOT NULL,
    login_logo_url text DEFAULT ''::text NOT NULL,
    login_background_image_url text DEFAULT ''::text NOT NULL,
    login_announcement text DEFAULT ''::text NOT NULL,
    login_heading text DEFAULT 'WaterSuite'::text NOT NULL,
    login_subheading text DEFAULT 'Employee and Resource Operations'::text NOT NULL,
    experience_builder_config jsonb DEFAULT jsonb_build_object('login_modules', '[]'::jsonb, 'employee_modules', '[]'::jsonb) NOT NULL,
    enable_retail_floor_simulation boolean DEFAULT false NOT NULL,
    CONSTRAINT organizations_default_shift_break_minutes_check CHECK ((default_shift_break_minutes >= 0)),
    CONSTRAINT organizations_experience_builder_config_shape_check CHECK (((jsonb_typeof(experience_builder_config) = 'object'::text) AND (jsonb_typeof(COALESCE((experience_builder_config -> 'login_modules'::text), '[]'::jsonb)) = 'array'::text) AND (jsonb_typeof(COALESCE((experience_builder_config -> 'employee_modules'::text), '[]'::jsonb)) = 'array'::text) AND (jsonb_typeof(COALESCE((experience_builder_config -> 'rocview_settings'::text), '{}'::jsonb)) = 'object'::text) AND (jsonb_typeof(COALESCE((experience_builder_config -> 'login_elements'::text), '{}'::jsonb)) = 'object'::text) AND (jsonb_typeof(COALESCE((experience_builder_config -> 'employee_elements'::text), '{}'::jsonb)) = 'object'::text))),
    CONSTRAINT organizations_extended_leave_threshold_days_check CHECK ((extended_leave_threshold_days >= 1)),
    CONSTRAINT organizations_login_accent_color_hex_check CHECK ((login_accent_color ~ '^#[A-Fa-f0-9]{6}$'::text)),
    CONSTRAINT organizations_login_primary_color_hex_check CHECK ((login_primary_color ~ '^#[A-Fa-f0-9]{6}$'::text)),
    CONSTRAINT organizations_onboarding_version_check CHECK ((onboarding_version >= 1)),
    CONSTRAINT organizations_timeline_window_hours_check CHECK ((default_timeline_window_hours = ANY (ARRAY[2, 4, 8]))),
    CONSTRAINT organizations_training_clock_in_early_check CHECK (((training_clock_in_early_min >= '-60'::integer) AND (training_clock_in_early_min <= 0))),
    CONSTRAINT organizations_training_clock_in_late_check CHECK (((training_clock_in_late_min >= 0) AND (training_clock_in_late_min <= 60))),
    CONSTRAINT organizations_training_clock_out_early_check CHECK (((training_clock_out_early_min >= '-60'::integer) AND (training_clock_out_early_min <= 0))),
    CONSTRAINT organizations_training_clock_out_late_check CHECK (((training_clock_out_late_min >= 0) AND (training_clock_out_late_min <= 60))),
    CONSTRAINT organizations_training_fake_employee_count_check CHECK (((training_fake_employee_count >= 5) AND (training_fake_employee_count <= 100))),
    CONSTRAINT organizations_training_no_show_rate_check CHECK (((training_no_show_rate_percent >= 0) AND (training_no_show_rate_percent <= 80))),
    CONSTRAINT organizations_training_task_ack_rate_check CHECK (((training_task_ack_rate_percent >= 0) AND (training_task_ack_rate_percent <= 100))),
    CONSTRAINT organizations_training_time_multiplier_check CHECK (((training_time_multiplier >= 1) AND (training_time_multiplier <= 100)))
);


-- Name: update_training_mode_settings(integer, integer, integer, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.update_training_mode_settings(p_training_time_multiplier integer, p_training_fake_employee_count integer, p_training_no_show_rate_percent integer, p_training_task_ack_rate_percent integer, p_training_clock_in_early_min integer, p_training_clock_in_late_min integer, p_training_clock_out_early_min integer, p_training_clock_out_late_min integer) RETURNS public.organizations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_row public.organizations%rowtype;
begin
  if not (public.is_admin(auth.uid()) or public.is_training_manager(auth.uid())) then
    raise exception 'Only admins or training managers can update training settings.';
  end if;

  v_org_id := public.current_organization_id(auth.uid());
  if v_org_id is null then
    raise exception 'Organization context is required.';
  end if;

  update public.organizations o
  set training_time_multiplier = least(greatest(coalesce(p_training_time_multiplier, 10), 1), 100),
      training_fake_employee_count = least(greatest(coalesce(p_training_fake_employee_count, 18), 5), 100),
      training_no_show_rate_percent = least(greatest(coalesce(p_training_no_show_rate_percent, 12), 0), 80),
      training_task_ack_rate_percent = least(greatest(coalesce(p_training_task_ack_rate_percent, 82), 0), 100),
      training_clock_in_early_min = least(greatest(coalesce(p_training_clock_in_early_min, -7), -60), 0),
      training_clock_in_late_min = least(greatest(coalesce(p_training_clock_in_late_min, 9), 0), 60),
      training_clock_out_early_min = least(greatest(coalesce(p_training_clock_out_early_min, -4), -60), 0),
      training_clock_out_late_min = least(greatest(coalesce(p_training_clock_out_late_min, 14), 0), 60)
  where o.id = v_org_id
  returning o.* into v_row;

  if v_row.id is null then
    raise exception 'Organization not found.';
  end if;

  return v_row;
end;
$$;


-- Name: employee_work_preferences; Type: TABLE; Schema: public; Owner: -

CREATE TABLE public.employee_work_preferences (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    employee_id uuid NOT NULL,
    max_weekly_hours integer,
    preferred_work_area_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    availability_notes text DEFAULT ''::text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT employee_work_preferences_max_weekly_hours_check CHECK (((max_weekly_hours >= 1) AND (max_weekly_hours <= 80)))
);


-- Name: upsert_my_work_preferences(integer, uuid[], text); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.upsert_my_work_preferences(p_max_weekly_hours integer DEFAULT NULL::integer, p_preferred_work_area_ids uuid[] DEFAULT '{}'::uuid[], p_availability_notes text DEFAULT ''::text) RETURNS public.employee_work_preferences
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_row public.employee_work_preferences%rowtype;
begin
  v_org_id := public.current_organization_id(auth.uid());
  if v_org_id is null then
    raise exception 'Organization context is required.';
  end if;

  insert into public.employee_work_preferences (
    organization_id,
    employee_id,
    max_weekly_hours,
    preferred_work_area_ids,
    availability_notes
  )
  values (
    v_org_id,
    auth.uid(),
    p_max_weekly_hours,
    coalesce(p_preferred_work_area_ids, '{}'),
    coalesce(p_availability_notes, '')
  )
  on conflict (employee_id)
  do update
  set max_weekly_hours = excluded.max_weekly_hours,
      preferred_work_area_ids = excluded.preferred_work_area_ids,
      availability_notes = excluded.availability_notes,
      updated_at = now()
  returning * into v_row;

  return v_row;
end;
$$;


-- Name: validate_task_assignment_within_shift(); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.validate_task_assignment_within_shift() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_task_start timestamptz;
  v_task_end timestamptz;
begin
  select t.start_at, t.end_at
    into v_task_start, v_task_end
  from public.tasks t
  where t.id = new.task_id;

  if v_task_start is null or v_task_end is null then
    raise exception 'Task not found for assignment.';
  end if;

  if not public.employee_has_covering_shift(new.employee_id, v_task_start, v_task_end) then
    raise exception 'Task time must be fully within an employee shift window.';
  end if;

  return new;
end;
$$;


-- Name: validate_task_time_for_existing_assignments(); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.validate_task_time_for_existing_assignments() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if exists (
    select 1
    from public.task_assignments ta
    where ta.task_id = new.id
      and not public.employee_has_covering_shift(ta.employee_id, new.start_at, new.end_at)
  ) then
    raise exception 'Task time must be fully within assigned employee shift window(s).';
  end if;

  return new;
end;
$$;


-- Name: verify_clock_in_location(uuid, uuid, double precision, double precision, double precision, boolean); Type: FUNCTION; Schema: public; Owner: -

CREATE FUNCTION public.verify_clock_in_location(p_organization_id uuid, p_shift_id uuid DEFAULT NULL::uuid, p_latitude double precision DEFAULT NULL::double precision, p_longitude double precision DEFAULT NULL::double precision, p_accuracy_meters double precision DEFAULT NULL::double precision, p_is_unscheduled boolean DEFAULT false) RETURNS TABLE(is_allowed boolean, message text, distance_meters double precision, location_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_shift_org_id uuid;
  v_shift_employee_id uuid;
  v_is_admin boolean := public.is_admin(auth.uid());
  v_nearest_name text;
  v_nearest_radius double precision;
  v_nearest_distance double precision;
  v_allowed_radius double precision;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required.';
  end if;

  if p_organization_id is null then
    raise exception 'Organization is required.';
  end if;

  if not public.is_same_org(p_organization_id, auth.uid()) then
    raise exception 'Cannot verify location across organizations.';
  end if;

  if p_shift_id is not null then
    select s.organization_id, s.employee_id
      into v_shift_org_id, v_shift_employee_id
    from public.shifts s
    where s.id = p_shift_id;

    if v_shift_org_id is null then
      raise exception 'Shift not found.';
    end if;

    if v_shift_org_id <> p_organization_id then
      raise exception 'Shift does not belong to organization.';
    end if;

    if not v_is_admin and v_shift_employee_id <> auth.uid() then
      raise exception 'You can only verify location for your own shift.';
    end if;
  end if;

  if p_latitude is null or p_longitude is null then
    return query select false, 'Location is required to clock in.', null::double precision, null::text;
    return;
  end if;

  select
    l.name,
    l.radius_meters,
    6371000 * 2 * asin(sqrt(
      power(sin(radians(l.latitude - p_latitude) / 2), 2)
      + cos(radians(p_latitude)) * cos(radians(l.latitude))
      * power(sin(radians(l.longitude - p_longitude) / 2), 2)
    ))
  into v_nearest_name, v_nearest_radius, v_nearest_distance
  from public.organization_clock_in_locations l
  where l.organization_id = p_organization_id
    and l.is_active = true
  order by
    6371000 * 2 * asin(sqrt(
      power(sin(radians(l.latitude - p_latitude) / 2), 2)
      + cos(radians(p_latitude)) * cos(radians(l.latitude))
      * power(sin(radians(l.longitude - p_longitude) / 2), 2)
    )) asc
  limit 1;

  if v_nearest_name is null then
    return query select false, 'No active clock-in locations are configured for your organization.', null::double precision, null::text;
    return;
  end if;

  v_allowed_radius := v_nearest_radius + greatest(coalesce(p_accuracy_meters, 0), 0);

  if v_nearest_distance <= v_allowed_radius then
    return query select true, format('Clock-in location verified at %s.', v_nearest_name), v_nearest_distance, v_nearest_name;
    return;
  end if;

  return query
  select
    false,
    format('Outside allowed range for %s. You are %.0fm away; limit %.0fm.', v_nearest_name, v_nearest_distance, v_allowed_radius),
    v_nearest_distance,
    v_nearest_name;
end;
$$;


